{
  "name": "GenICam工业相机",
  "name_en": "GenICam machine vision camera",
  "manufacturer": "",
  "description": "符合 GenICam/GenTL 标准的工业相机或成像设备，用于实验室中的图像采集、机器视觉、显微成像和自动化检测。此类设备通常可被枚举、连接，并持续输出二维图像数据流。",
  "description_en": "A GenICam/GenTL-compatible machine vision camera or imaging device used in laboratories for image acquisition, machine vision, microscopy, and automated inspection. Such devices can typically be enumerated, connected, and used to stream 2D image data.",
  "tag_hints": [
    "GenICam",
    "GenTL",
    "machine vision camera",
    "image acquisition",
    "2D imaging",
    "industrial camera",
    "camera enumeration"
  ],
  "actions": [
    {
      "action_name": "auto-image_acquirers",
      "description": "列出已创建的相机图像采集会话。",
      "description_en": "List the created image acquisition sessions for cameras."
    },
    {
      "action_name": "auto-timer",
      "description": "获取采集管理计时器。",
      "description_en": "Get the acquisition management timer."
    },
    {
      "action_name": "auto-reset",
      "description": "将相机采集系统重置到初始状态。",
      "description_en": "Reset the camera acquisition system to its initial state."
    },
    {
      "action_name": "auto-cti_files",
      "description": "获取已加载的 GenTL CTI 文件列表。",
      "description_en": "Get the list of loaded GenTL CTI files."
    },
    {
      "action_name": "auto-files",
      "description": "获取已加载的 GenTL CTI 文件列表。",
      "description_en": "Get the list of loaded GenTL CTI files."
    },
    {
      "action_name": "auto-device_info_list",
      "description": "获取当前可发现的相机或成像设备信息列表。",
      "description_en": "Get the list of currently discoverable cameras or imaging devices."
    },
    {
      "action_name": "auto-timeout_for_update",
      "description": "获取/设置设备枚举超时时间。",
      "description_en": "Get/set the device enumeration timeout."
    },
    {
      "action_name": "auto-has_revised_device_info_list",
      "description": "获取/设置设备信息列表是否已更新的标志。",
      "description_en": "Get/set the flag indicating whether the device information list has been updated."
    },
    {
      "action_name": "auto-create",
      "description": "根据搜索条件连接选定相机并创建图像采集会话。",
      "description_en": "Connect to a selected camera and create an image acquisition session based on search criteria."
    },
    {
      "action_name": "auto-create_image_acquirer",
      "description": "为选定相机创建图像采集会话。",
      "description_en": "Create an image acquisition session for the selected camera."
    },
    {
      "action_name": "auto-add_cti_file",
      "description": "添加 GenTL CTI 文件以支持相机发现和连接。",
      "description_en": "Add a GenTL CTI file to support camera discovery and connection."
    },
    {
      "action_name": "auto-add_file",
      "description": "添加 GenTL CTI 文件以支持相机发现和连接。",
      "description_en": "Add a GenTL CTI file to support camera discovery and connection."
    },
    {
      "action_name": "auto-remove_cti_file",
      "description": "移除指定的 GenTL CTI 文件。",
      "description_en": "Remove the specified GenTL CTI file."
    },
    {
      "action_name": "auto-remove_file",
      "description": "移除指定的 GenTL CTI 文件。",
      "description_en": "Remove the specified GenTL CTI file."
    },
    {
      "action_name": "auto-remove_cti_files",
      "description": "移除全部 GenTL CTI 文件。",
      "description_en": "Remove all GenTL CTI files."
    },
    {
      "action_name": "auto-remove_files",
      "description": "移除全部 GenTL CTI 文件。",
      "description_en": "Remove all GenTL CTI files."
    },
    {
      "action_name": "auto-update_device_info_list",
      "description": "刷新可发现的相机或成像设备列表。",
      "description_en": "Refresh the list of discoverable cameras or imaging devices."
    },
    {
      "action_name": "auto-update",
      "description": "刷新可发现的相机或成像设备列表。",
      "description_en": "Refresh the list of discoverable cameras or imaging devices."
    },
    {
      "action_name": "auto-compose_message",
      "description": "生成与相机采集相关的消息文本。",
      "description_en": "Compose a message related to camera acquisition."
    }
  ]
}

